// A synchronous gRPC call: block until reply OR the deadline fires.
ctx, cancel := context.WithTimeout(ctx, 200*time.Millisecond)
defer cancel() // the budget shrinks at each downstream hop

// propagate a trace ID so the request is traceable end-to-end
ctx = metadata.AppendToOutgoingContext(ctx, "x-request-id", reqID)

resp, err := client.GetOrder(ctx, &orderpb.GetOrderRequest{Id: "o-42"})
if err != nil {
	// includes DeadlineExceeded on timeout — fail fast, don't pile up
	log.Printf("call failed: %v", err)
	return
}
fmt.Println(resp.Status)
